package io.github.ningpp.compat;

/** Replacement for System.Runtime.InteropServices.InvalidOleVariantTypeException (generated by CSharpToJava converter). */
public class InvalidOleVariantTypeException extends SystemException {
    public InvalidOleVariantTypeException() { super(); }
    public InvalidOleVariantTypeException(String message) { super(message); }
    public InvalidOleVariantTypeException(String message, Throwable cause) { super(message, cause); }
}
